-- Venue Live Guest "Ulang Tahun Demon Hunter". Aditif & idempoten. Jalankan SETELAH admin-live-event-aqiqah.sql (jenis acara demonhunter), admin-live-theme.sql, admin-live-decor.sql, admin-live-decor-avatars.sql, dan admin-live-decor-garden-layout.sql (skrip tata letak itu melewati venue ini karena ukuran/posisi dekornya diatur sendiri).
insert into public.live_venues (key, name, event_type, areas, max_guests, active, sort, bg_pos, nm_theme)
select 'demonhunter', 'Ulang Tahun Demon Hunter', 'demonhunter', coalesce((select areas from public.live_venues where key = 'little-ballerina'), '[]'::jsonb), 300, false, 177, 'center 38%',
  $t${"name":"Demon Hunter","orn":"diamond","ui":{"ivory":"#F5EEFB","white":"#FFFFFF","soft":"#E3D2F3","soft2":"#C8A8E6","accent":"#B03FD0","deep":"#3F1D63","ink":"#2E1450","mute":"#7E6A9A","line":"#DCC8F0","serif":"\"Fredoka\",system-ui,sans-serif","sans":"Inter,system-ui,sans-serif","rad":18,"btnr":14,"btnt":"none","btnls":".02em"},"mono":{"font":"\"Fredoka\",system-ui,sans-serif","it":0,"paper":"#FBF7FF","ink":"#2E1450","accent":"#B03FD0","gold":"#C9A24A","leaf":"#E3D2F3","hbg":"rgba(245,238,251,.94)","hline":"#C9A24A","motif":"diamond"},"hud":{"bg":"rgba(46,20,80,.9)","acc":"#E9B8FF","on":"#2E1450"},"scr":{"wine":"#3F1D63","veil":"245,238,251"}}$t$::jsonb
